formulas.expression:
IF(
   AND(
      NOT(ISBLANK($Record.Account.PFS_Owner_Email__c)),
      ISBLANK($Record.End_User_Account__c),
      {!Get_Organization.IsSandbox}
   ),
   $Record.Account.PFS_Owner_Email__c & ".invalid",

   IF(
      AND(
         NOT(ISBLANK($Record.Account.PFS_Owner_Email__c)),
         ISBLANK($Record.End_User_Account__c),
         NOT({!Get_Organization.IsSandbox})
      ),
      $Record.Account.PFS_Owner_Email__c,

      IF(
         AND(
            NOT(ISBLANK($Record.End_User_Account__r.PFS_Owner_Email__c)),
            {!Get_Organization.IsSandbox}
         ),
         $Record.End_User_Account__r.PFS_Owner_Email__c & ".invalid",
         $Record.End_User_Account__r.PFS_Owner_Email__c
      )
   )
)
